schema:
entity Picker {
    user: User,
};

entity ForkliftOperator {
    user: User,
};

entity ZoneSupervisor {
    user: User,
};

entity WarehouseManager {
    user: User,
};

entity SecurityOfficer {
    user: User,
};

entity User in [Picker, ForkliftOperator, ZoneSupervisor, WarehouseManager, SecurityOfficer];

entity Zone {
    zoneCode: String,
    sensitivity: String,
    zoneGroup: String,
    isLocked: Bool,
    operationalStatus: String,
};

entity Order {
    requestedBy: User,
    picker: User,
    items: Set<String>,
    itemCount: Long,
    pickListCode: String,
    status: String,
    destinationZone: Zone,
    releaseTime: datetime,
    crossesBulkPickThreshold: Bool,
};

action pickOrder appliesTo {
    principal: [User, Picker, ForkliftOperator],
    resource: [Order],
    context: {
        currentTime: datetime,
        hasBadgedInOnSiteForShift: Bool,
        emergencyDeclared: Bool,
    },
};

entity Role enum ["recruiter", "hiringManager", "interviewer", "coordinator"];

entity Person {
    roles: Set<Role>,
    piiClearance: Long,
};

entity Candidate;

entity Application {
    candidate: Candidate,
    referrer?: Person,
    hiringTeam: Set<Person>,
    reqCode: String,
    piiSensitivity: Long,
    status: String,
};

entity InterviewFeedback {
    application: Application,
    interviewer: Person,
    candidate: Candidate,
    status: String,
};

entity Offer {
    application: Application,
    extender: Person,
    compensation: decimal,
    signingBonus: decimal,
    status: String,
};

action approveOffer appliesTo {
    principal: [Person],
    resource: [Offer],
    context: {
        isFromCorporateNetwork: Bool,
        currentTime: datetime,
        hasExecutiveApproval: Bool,
        isWithinPermittedWindow: Bool,
    },
};

entity User;

entity Patient;

entity MedicalTechnologist {
    user: User,
};

entity Pathologist {
    user: User,
};

entity OrderingProvider {
    user: User,
};

entity LabDirector {
    user: User,
};

entity LabResult {
    patient: Patient,
    orderingProvider: OrderingProvider,
    verifiedBy?: MedicalTechnologist,
    sensitivityLevel: String,
    criticalValueFlag: Bool,
    releasedToPatientPortalAt?: datetime,
    status: String,
    isVerified: Bool,
};

entity LabOrder {
    patient: Patient,
    orderingProvider: OrderingProvider,
    testCode: String,
    status: String,
};

action releaseLabResult appliesTo {
    principal: [Pathologist, OrderingProvider],
    resource: [LabResult],
    context: {
        currentTime: datetime,
        mfaUsed: Bool,
        onHospitalNetwork: Bool,
        emergencyRelease: Bool,
        coverageAuthorized: Bool,
    },
};

entity User {
    isNetworkEngineer: Bool,
    isSeniorEngineer: Bool,
    isChangeManager: Bool,
    isCabApprover: Bool,
    isAuditor: Bool,
    grantedChangeAuthorityLevel: Long,
};

entity ChangeStatus enum ["Approved", "NotApproved"];

entity ChangeRequest {
    requestedBy: User,
    implementedBy?: User,
    approvedBy?: User,
    assessedRisk: Long,
    affectedNodeCount: Long,
    rollbackStepCount: Long,
    estimatedCost: decimal,
    changeCode: String,
    isEmergency: Bool,
    changeCategory: String,
    currentStatus: ChangeStatus,
    maintenanceWindowStart: datetime,
    estimatedCostCents: Long,
};

entity ImplementationRecord {
    change: ChangeRequest,
    carriedOutBy: User,
    carriedOutAt: datetime,
};

action approveChange appliesTo {
    principal: [User],
    resource: [ChangeRequest],
    context: {
        currentTime: datetime,
        fromManagementNetwork: Bool,
        changeFreezeWaiverGranted: Bool,
        majorIncidentDeclared: Bool,
        cabSignoffCostThreshold: decimal,
        cabSignoffCostThresholdCents: Long,
    },
};

action implementChange appliesTo {
    principal: [User],
    resource: [ChangeRequest],
    context: {
        currentTime: datetime,
        fromManagementNetwork: Bool,
        changeFreezeWaiverGranted: Bool,
        majorIncidentDeclared: Bool,
    },
};

entity Role enum ["Operator", "Technician", "FleetAdmin", "ServiceAccount"];

entity SiteGroup in [SiteGroup];

entity Requester in [SiteGroup] {
    roles: Set<Role>,
    clearance: Long,
    groups: Set<SiteGroup>,
};

entity Device {
    owner: Requester,
    siteGroup: SiteGroup,
    firmwareTags: Set<String>,
    maintenanceMode: Bool,
    status: String,
};

entity TelemetryRecord {
    device: Device,
    sensitivity: Long,
};

entity Command;

action readTelemetry appliesTo {
    principal: [Requester],
    resource: [TelemetryRecord],
};

entity Deployer {
    user: User,
};

entity Maintainer {
    user: User,
};

entity ClusterOperator;

entity User in [Deployer, Maintainer, ClusterOperator] {
    clearance: Long,
    grantedScope: String,
    groupMembership: Set<String>,
};

entity ServiceAccount {
    clearance: Long,
    grantedScope: String,
    groupMembership: Set<String>,
};

entity Namespace;

entity Workload;

entity NamespaceSecret {
    namespace: Namespace,
    ownerUser?: User,
    ownerServiceAccount?: ServiceAccount,
    sensitivity: Long,
    status: String,
};

entity ServiceAccountToken {
    expiresAt: datetime,
};

action readNamespaceSecret appliesTo {
    principal: [User, ServiceAccount],
    resource: [NamespaceSecret],
    context: {
        sourceIp: ipaddr,
        currentTime: datetime,
        emergencyChange: Bool,
        mfaUsed: Bool,
        serviceAccountToken: ServiceAccountToken,
    },
};

entity Person {
    roles: Set<Role>,
    clearedLevel: Long,
    ward: String,
};

entity Role enum ["attendingPhysician", "resident", "nurse", "pharmacist"];

entity Patient;

entity MedicalRecord {
    patient: Patient,
    careTeam: Set<Person>,
    ward: String,
    sensitivity: Long,
    status: String,
    isSealed: Bool,
};

entity Prescription {
    patient: Patient,
    prescriber: Person,
    status: String,
};

entity LabOrder {
    patient: Patient,
};

action viewMedicalRecord appliesTo {
    principal: [Person],
    resource: [MedicalRecord],
    context: {
        currentShift: String,
        emergencyDeclared: Bool,
        mfaUsed: Bool,
    },
};

entity User {
    roles: Set<Role>,
};

entity Role enum ["clerk", "approver", "financeManager", "auditor"];

entity InvoiceStatus enum ["submitted", "approved"];

entity Invoice {
    creator: User,
    approver?: User,
    amount: decimal,
    surcharge: decimal,
    lineItemCount: Long,
    status: InvoiceStatus,
    costCenter: String,
    submittedAt: datetime,
};

entity Payment {
    invoice: Invoice,
    issuer: User,
    amount: decimal,
};

action approveInvoice appliesTo {
    principal: [User],
    resource: [Invoice],
    context: {
        currentTime: datetime,
        onCorporateNetwork: Bool,
        emergencyDeclared: Bool,
    },
};

action issuePayment appliesTo {
    principal: [User],
    resource: [Payment],
    context: {
        currentTime: datetime,
        onCorporateNetwork: Bool,
        emergencyDeclared: Bool,
    },
};

entity Role enum ["InstructorOfRecord", "TeachingAssistant", "Learner", "Coordinator"];

entity Person {
    roles: Set<Role>,
    completedLevel: Long,
};

entity Course;

entity Module {
    course: Course,
    instructorOfRecord: Person,
    roster: Set<Person>,
    prerequisiteLevel: Long,
    releaseTime: datetime,
    locked: Bool,
    status: String,
};

entity GradeEntry {
    learner: Person,
    module: Module,
    postedBy: Person,
    status: String,
};

action enterGrade appliesTo {
    principal: [Person],
    resource: [GradeEntry],
    context: {
        currentTime: datetime,
        onInstitutionNetwork: Bool,
        previewWindow: { start: datetime, end: datetime },
    },
};

entity Role enum ["committer", "approver", "releaseManager", "siteReliabilityEngineer"];

entity Team;

entity User {
    roles: Set<Role>,
    team: Team,
};

entity Artifact {
    builtBy: User,
    hasBeenSigned: Bool,
    buildTags: Set<String>,
    status: String,
    buildSucceeded: Bool,
};

entity Deployment {
    committer: User,
    approver: User,
    targetEnvironment: String,
    changeRiskLevel: String,
    artifact: Artifact,
    status: String,
};

action signArtifact appliesTo {
    principal: [User],
    resource: [Artifact],
    context: {
        currentTime: datetime,
        sourceNetworkAddress: ipaddr,
        isEmergencyChange: Bool,
        sourceNetworkIsCorporateVpn: Bool,
    },
};

entity Role enum ["Planner", "ShiftSupervisor", "Operator", "ControlRoomOperator", "Auditor"];

entity User {
    roles: Set<Role>,
};

entity SwitchingOrder {
    planner: User,
    designatedOperator: User,
    feeder: String,
    voltageLevel: decimal,
    circuitCount: Long,
    status: String,
    scheduledStart: datetime,
    scheduledEnd: datetime,
};

entity LockoutTag {
    order: SwitchingOrder,
    appliedBy: User,
    feeder: String,
    status: LockoutTagStatus,
};

entity Feeder;

entity SwitchingOrderStatus;

entity LockoutTagStatus;

action authorizeSwitchingOrder appliesTo {
    principal: [User],
    resource: [SwitchingOrder],
    context: {
        currentTime: datetime,
        fromControlSystemNetwork: Bool,
        lockoutTagoutVerified: Bool,
        outageEmergencyDeclared: Bool,
        shiftSupervisorVoltageThreshold: decimal,
        voltageAboveShiftSupervisorThreshold: Bool,
    },
};

entity Role enum ["Developer", "Reviewer", "Maintainer", "SecurityLead"];

entity User {
    roles: Set<Role>,
};

entity Team;

entity Repository {
    owner: User,
    team: Team,
    sensitivity: String,
    defaultBranchProtected: Bool,
    topics: Set<String>,
    status: String,
};

entity Branch {
    name: String,
    protected: Bool,
};

entity PullRequest {
    repository: Repository,
    author: User,
    approvedBy: Set<User>,
    targetBranch: Branch,
    approvalCount: Long,
    linesChanged: Long,
    securityReviewRequired: Bool,
    status: String,
    designatedRole: Role,
};

action reviewPullRequest appliesTo {
    principal: [User],
    resource: [PullRequest],
    context: {
        extraScrutinyLineThreshold: Long,
    },
};

action mergePullRequest appliesTo {
    principal: [User],
    resource: [PullRequest],
};

entity User {
    isPortingSpecialist: Bool,
    isPortingSupervisor: Bool,
    isFraudReviewer: Bool,
    isLineTechnician: Bool,
    isAuditor: Bool,
};

entity PortRequest {
    initiatedBy: User,
    authorizedBy?: User,
    technicianAssignedTo: User,
    accountNumbers: Set<String>,
    numberBlockSize: Long,
    gainingCarrierCode: String,
    portType: String,
    subscriberRegion: String,
    status: String,
    requestedAt: datetime,
    includesFlaggedOrHighValueLine: Bool,
    currentTime: datetime,
    isFromOwnOperationsNetwork: Bool,
    portFreezeOverrideDeclared: Bool,
    regulatorEscalationInEffect: Bool,
};

entity PortCompletion {
    request: PortRequest,
    completedBy: User,
    portedAt: datetime,
};

action submitPortRequest appliesTo {
    principal: [User],
    resource: [PortRequest],
};

action authorizePortRequest appliesTo {
    principal: [User],
    resource: [PortRequest],
};

action completeCutover appliesTo {
    principal: [User],
    resource: [PortCompletion],
};

entity Role enum ["Reviewer", "ProgramOfficer", "GrantsOfficer", "Applicant"];

entity User {
    roles: Set<Role>,
    approvalAuthority: Long,
};

entity Application {
    applicant: User,
    assignedReviewers: Set<User>,
    fundingTier: Long,
    requestedAmount: decimal,
    programCode: String,
    status: String,
};

entity Award {
    application: Application,
    approvedBy?: User,
    obligatedBy?: User,
    amount: decimal,
    highRisk: Bool,
    status: String,
};

action approveAward appliesTo {
    principal: [User],
    resource: [Award],
    context: {
        currentTime: datetime,
        fromGovernmentNetwork: Bool,
        emergencyDeclared: Bool,
    },
};

action obligateFunds appliesTo {
    principal: [User],
    resource: [Award],
    context: {
        currentTime: datetime,
        fromGovernmentNetwork: Bool,
        emergencyDeclared: Bool,
    },
};

entity Role enum ["operator", "technician", "fleetAdmin", "serviceAccount"];

entity DeviceStatus enum ["active", "provisioned", "decommissioned"];

entity User {
    roles: Set<Role>,
};

entity ServiceAccount;

entity SiteGroup;

entity MaintenanceWindow {
    startTime: datetime,
    endTime: datetime,
    permitted: Bool,
};

entity Device {
    owner: User,
    siteGroup: SiteGroup,
    firmwareTags: Set<String>,
    maintenanceMode: Bool,
    status: DeviceStatus,
};

entity Telemetry;

entity Command {
    targetDevice: Device,
};

action sendCommand appliesTo {
    principal: [User],
    resource: [Command],
    context: {
        sourceIp: ipaddr,
        currentTime: datetime,
        maintenanceWindow: MaintenanceWindow,
    },
};

entity Role enum ["operator", "inspector", "qualityManager", "productionSupervisor", "auditor"];

entity WorkOrderStatus enum ["created", "inProgress", "signedOff", "released"];

entity Person {
    roles: Set<Role>,
};

entity WorkOrder {
    operator: Person,
    inspector: Person,
    partCode: String,
    defectCount: Long,
    holdFlag: Bool,
    status: WorkOrderStatus,
    station: String,
    creationTime: datetime,
    partCodeAcceptable: Bool,
    acceptanceThreshold: Long,
};

entity ProductionRelease {
    workOrder: WorkOrder,
};

entity QualityLog;

action createWorkOrder appliesTo {
    principal: [Person],
    resource: [WorkOrder],
    context: {
        currentTime: datetime,
        fromPlantNetwork: Bool,
        deviationAuthorized: Bool,
    },
};

action startWork appliesTo {
    principal: [Person],
    resource: [WorkOrder],
    context: {
        currentTime: datetime,
        fromPlantNetwork: Bool,
        deviationAuthorized: Bool,
    },
};

action signOffWorkOrder appliesTo {
    principal: [Person],
    resource: [WorkOrder],
    context: {
        currentTime: datetime,
        fromPlantNetwork: Bool,
        deviationAuthorized: Bool,
        partCodeMatches: Bool,
        hasControlledPartPrefix: Bool,
        acceptanceThreshold: Long,
    },
};

action releaseToProduction appliesTo {
    principal: [Person],
    resource: [ProductionRelease],
    context: {
        currentTime: datetime,
        fromPlantNetwork: Bool,
        deviationAuthorized: Bool,
    },
};

action viewQualityLog appliesTo {
    principal: [Person],
    resource: [QualityLog],
    context: {
        currentTime: datetime,
        fromPlantNetwork: Bool,
        deviationAuthorized: Bool,
    },
};

entity Person {
    roles: Set<Role>,
    clearance: String,
    recusedCases: Set<Case>,
};

entity Role enum ["AdjudicationOfficer", "SupervisoryOfficer", "BackgroundInvestigator", "RecordsClerk"];

entity Applicant;

entity Team;

entity FieldOffice;

entity Case {
    applicant: Applicant,
    assignedOfficer: Person,
    caseTeam: Team,
    fieldOffice: FieldOffice,
    status: String,
};

entity SecurityCheck {
    case: Case,
    investigator: Person,
    status: String,
    permittedWindowStart: datetime,
    permittedWindowEnd: datetime,
};

entity ApplicantRecord {
    applicant: Applicant,
    assignedOfficer: Person,
    needToKnowTeam: Team,
    dataSensitivity: String,
    status: String,
};

action clearSecurityCheck appliesTo {
    principal: [Person],
    resource: [SecurityCheck],
    context: {
        onGovernmentNetwork: Bool,
        currentTime: datetime,
        supervisorApprovalPresent: Bool,
    },
};

entity Role enum ["developer", "reviewer", "maintainer", "securityLead"];

entity ClearanceLevel enum ["public", "internal", "confidential", "restricted"];

entity RepositoryLifecycleStatus enum ["active", "archived"];

entity User {
    roles: Set<Role>,
    clearanceLevel: ClearanceLevel,
};

entity Team;

entity Repository {
    owner: User,
    team: Team,
    sensitivityClassification: ClearanceLevel,
    defaultBranchProtected: Bool,
    topicTags: Set<String>,
    lifecycleStatus: RepositoryLifecycleStatus,
};

entity Branch {
    name: String,
    protected: Bool,
};

entity PullRequest {
    repository: Repository,
    author: User,
    approvers: Set<User>,
    targetBranch: Branch,
    approvalCount: Long,
    linesChanged: Long,
    requiresSecurityReview: Bool,
    status: String,
};

action cloneRepository appliesTo {
    principal: [User],
    resource: [Repository],
};

entity User {
    roles: Set<Role>,
};

entity Role enum ["Advertiser", "AccountManager", "BrandSafetyReviewer", "CampaignDirector"];

entity CampaignStatus enum ["Draft", "BudgetApproved", "Launched"];

entity Campaign {
    advertiser: User,
    preparedBy: User,
    budget: Long,
    contingency: Long,
    budgetTier: String,
    riskLabels: Set<String>,
    scheduledStart: datetime,
    status: CampaignStatus,
};

entity Creative;

action approveBudget appliesTo {
    principal: [User],
    resource: [Campaign],
    context: {
        currentTime: datetime,
        mfaUsed: Bool,
        trustedDevice: Bool,
        emergencyLaunchDeclared: Bool,
        budgetContingencyThreshold: Long,
    },
};

action launchCampaign appliesTo {
    principal: [User],
    resource: [Campaign],
    context: {
        currentTime: datetime,
        mfaUsed: Bool,
        trustedDevice: Bool,
        emergencyLaunchDeclared: Bool,
        requiredRiskLabel: String,
    },
};

entity User {
    isCommitter: Bool,
    isApprover: Bool,
    isReleaseManager: Bool,
    isSre: Bool,
    deployTier: String,
};

entity Artifact {
    builtBy: User,
    isSigned: Bool,
    buildTags: Set<String>,
    status: String,
};

entity Deployment {
    committer: User,
    approver: User,
    targetEnvironment: String,
    changeRisk: Long,
    artifact: Artifact,
    status: String,
    submittedForReview: Bool,
};

action approveDeployment appliesTo {
    principal: [User],
    resource: [Deployment],
    context: {
        currentTime: datetime,
        sourceIp: ipaddr,
        emergencyChange: Bool,
        extraScrutinyThreshold: Long,
    },
};
